cd /workspaces/learn-p5 && node -e "
const fs=require('fs'),path=require('path'),y=require('js-yaml');
const files=fs.readdirSync('src/data/courses').filter(f=>f.endsWith('.yaml'));
let counts={}, sample={}, totalTasks=0, totalRules=0, exWithTasks=0, exWithSolution=0, exWithTaskSolutions=0;
const typeCounts={}; const nameCounts={};
for(const f of files){
  const c=y.load(fs.readFileSync(path.join('src/data/courses',f),'utf8'));
  for(const ex of c.exercises||[]){
    if(ex.solution) exWithSolution++;
    if(ex.tasks){
      exWithTasks++;
      const last=ex.tasks[ex.tasks.length-1];
      if(last && last.solution) exWithTaskSolutions++;
      for(const t of ex.tasks){
        totalTasks++;
        for(const r of t.validation||[]){
          totalRules++;
          typeCounts[r.type]=(typeCounts[r.type]||0)+1;
          if(r.name) nameCounts[r.name]=(nameCounts[r.name]||0)+1;
        }
      }
    }
  }
}
console.log('courses',files.length,'exercisesWithTasks',exWithTasks,'exercisesWithExerciseLevelSolution',exWithSolution,'exercisesWithFinalTaskSolution',exWithTaskSolutions);
console.log('total tasks',totalTasks,'total rules',totalRules);
console.log('rule types:',typeCounts);
console.log('top rule names:',Object.entries(nameCounts).sort((a,b)=>b[1]-a[1]));
"

cd /workspaces/learn-p5 && node -e "
const fs=require('fs'),path=require('path'),y=require('js-yaml');
const files=fs.readdirSync('src/data/courses').filter(f=>f.endsWith('.yaml'));
let tasksWithOwnSolution=0, tasksWithValidation=0, tasksWithNoValidation=0, finalTasks=0, finalTasksNoSolution=0;
let noValidationTasks=[];
const canvasSizeUses=[], expectedPixelsUses=[];
for(const f of files){
  const c=y.load(fs.readFileSync(path.join('src/data/courses',f),'utf8'));
  for(const ex of c.exercises||[]){
    const tasks=ex.tasks||[];
    tasks.forEach((t,i)=>{
      if(t.solution) tasksWithOwnSolution++;
      const rules=t.validation||[];
      if(rules.length) tasksWithValidation++; else { tasksWithNoValidation++; noValidationTasks.push({course:f,ex:ex.id,task:t.id}); }
      if(i===tasks.length-1){ finalTasks++; if(!t.solution) finalTasksNoSolution++; }
      for(const r of rules){
        if(r.type==='canvasSize') canvasSizeUses.push({f,ex:ex.id,t:t.id});
        if(r.type==='expectedPixels') expectedPixelsUses.push({f,ex:ex.id,t:t.id});
      }
    });
  }
}
console.log('tasks with own solution:', tasksWithOwnSolution);
console.log('tasks with validation:', tasksWithValidation, 'no validation:', tasksWithNoValidation);
console.log('final tasks:', finalTasks, 'final tasks without own solution:', finalTasksNoSolution);
console.log('canvasSize rule uses:', canvasSizeUses.length, 'expectedPixels uses:', expectedPixelsUses.length);
console.log('no-validation tasks:', JSON.stringify(noValidationTasks,null,1));
"

