function findCallsByName(code,name){const sanitized=stripIgnored(code);const calls=[];const re=new RegExp('\\\\b'+name+'\\\\b','g');const idxs=[];let m;while((m=re.exec(sanitized))!==null)idxs.push(m.index+m[0].length);for(const start of idxs){let i=start;while(i<sanitized.length&&sanitized[i]!=='(')i++;if(sanitized[i]!=='(')continue;let depth=0,argStart=i+1;const args=[];for(let j=i;j<sanitized.length;j++){const ch=sanitized[j];if(ch==='(')depth++;else if(ch===')'){depth--;if(depth===0){const raw=sanitized.slice(argStart,j);if(raw.trim().length>0)args.push(raw);calls.push(args.map(a=>a.trim()).filter(a=>a.length>0));break;}}else if(ch===','&&depth===1){args.push(sanitized.slice(argStart,j));argStart=j+1;}}}
