import esbuild from "esbuild";
import { parser } from "@lezer/javascript";
import fs from "fs";
import os from "os";
import path from "path";
import { pathToFileURL } from "url";

const result = await esbuild.build({
  entryPoints: [path.resolve("src/utils/editor/validation.ts")],
  bundle: true,
  platform: "node",
  format: "esm",
  write: false,
  logLevel: "silent",
});
const tmp = path.join(os.tmpdir(), `vtest-${process.pid}.mjs`);
fs.writeFileSync(tmp, result.outputFiles[0].text);
const V = await import(pathToFileURL(tmp).href);
fs.unlinkSync(tmp);

function analyzeCode(code) {
  const tree = parser.parse(code);
  return V.analyze({ cursor: () => tree.cursor(), slice: (f, t) => code.slice(f, t) });
}
function evalCode(code, rules) {
  return V.evaluateRules(analyzeCode(code), rules);
}

let pass = 0, fail = 0;
function check(label, cond, extra) {
  if (cond) { pass++; console.log("  ok", label); }
  else { fail++; console.log("  FAIL", label, extra ?? ""); }
}

// --- H1: definitions must NOT count as calls ---
check("def-only circle fails functionCall", !evalCode("function circle(a,b,c){}", [{type:"functionCall", name:"circle", exactArgs:3}]).passed);
check("def-only via arrow fails functionCall", !evalCode("const circle = (a,b,c) => a;", [{type:"functionCall", name:"circle", exactArgs:3}]).passed);
// --- H2: comments must NOT satisfy functionExists ---
check("comment-only mousePressed fails functionExists", !evalCode("// function mousePressed() {}\nfunction setup(){}", [{type:"functionExists", name:"mousePressed"}]).passed);
// --- arrow/member defs satisfy functionExists ---
check("arrow def satisfies functionExists", evalCode("const mousePressed = () => {};", [{type:"functionExists", name:"mousePressed"}]).passed);
check("function decl satisfies functionExists", evalCode("function keyPressed() {}", [{type:"functionExists", name:"keyPressed"}]).passed);
check("object shorthand method satisfies functionExists", evalCode("const h = { mousePressed() {} };", [{type:"functionExists", name:"mousePressed"}]).passed);
check("class method satisfies functionExists", evalCode("class C { keyPressed() {} }", [{type:"functionExists", name:"keyPressed"}]).passed);
// --- real calls ---
check("real call passes", evalCode("circle(1,2,3);", [{type:"functionCall", name:"circle", exactArgs:3}]).passed);
check("wrong arg count fails", !evalCode("circle(1,2);", [{type:"functionCall", name:"circle", exactArgs:3}]).passed);
check("member call passes", evalCode("v.add(1,2);", [{type:"functionCall", name:"add", exactArgs:2}]).passed);
check("member call name extracted", evalCode("v.heading();", [{type:"functionCall", name:"heading", minArgs:0}]).passed);
check("nested parens = 1 arg", evalCode("f((1,2));", [{type:"functionCall", name:"f", exactArgs:1}]).passed);
check("empty args = 0", evalCode("f();", [{type:"functionCall", name:"f", exactArgs:0}]).passed);
check("string with comma = 1 arg", evalCode("text('a,b', 1, 2);", [{type:"functionCall", name:"text", exactArgs:3}]).passed);
check("new p5 counted (name p5)", evalCode("new p5(undefined, el);", [{type:"functionCall", name:"p5", exactArgs:2}]).passed);
// --- canvasSize ---
check("canvas size ok", evalCode("createCanvas(400,400);", [{type:"canvasSize", width:400, height:400}]).passed);
check("canvas size mismatch", !evalCode("createCanvas(300,300);", [{type:"canvasSize", width:400, height:400}]).passed);
check("no canvas fails", !evalCode("background(0);", [{type:"canvasSize", width:400, height:400}]).passed);
check("non-literal canvas fails", !evalCode("createCanvas(w,h);", [{type:"canvasSize", width:400, height:400}]).passed);
// --- schema ---
check("typo field flagged", V.schemaErrors([{type:"functionCall", name:"circle", excatArgs:3}]).length === 1);
check("valid rules clean", V.schemaErrors([{type:"functionCall", name:"circle", exactArgs:3}]).length === 0);
check("unknown type flagged", V.schemaErrors([{type:"bogus"}]).length === 1);
check("missing required flagged", V.schemaErrors([{type:"canvasSize", width:400}]).length === 1);
// --- pixel helpers ---
check("pixelMatches within tol", V.pixelMatches([255,100,200], [255,105,180], 120));
check("pixelMatches out of tol", !V.pixelMatches([0,0,0], [255,255,255], 30));

// --- run against a real solution (data.yaml exercise-2) ---
const dataSol = `let count = 0;
function setup() { createCanvas(400, 400); count = getItem("count") || 0; }
function draw() { background(240); text(count, 200, 200); }
function mousePressed() { count++; storeItem("count", count); }`;
const rules = [
  {type:"functionCall", name:"getItem", exactArgs:1},
  {type:"functionCall", name:"storeItem", exactArgs:2},
  {type:"functionExists", name:"mousePressed"},
];
const r = evalCode(dataSol, rules);
check("real solution passes", r.passed, JSON.stringify(r));
// sanity: comment-only storeItem should NOT satisfy the call rule
check("commented call fails", !evalCode("// storeItem(1,2)\nfunction setup(){}", [{type:"functionCall", name:"storeItem", exactArgs:2}]).passed);

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
EOF
